// receipt.cpp - Formatted output with <iomanip>
#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    string item1 = "Notebook", item2 = "Pen", item3 = "Geometry Box";
    int q1 = 4, q2 = 10, q3 = 1;
    double p1 = 45.5, p2 = 10, p3 = 120.75;

    cout << fixed << setprecision(2);
    cout << left << setw(15) << "Item" << right << setw(5) << "Qty"
         << setw(10) << "Price" << setw(10) << "Amount" << endl;
    cout << "----------------------------------------" << endl;
    cout << left << setw(15) << item1 << right << setw(5) << q1
         << setw(10) << p1 << setw(10) << q1 * p1 << endl;
    cout << left << setw(15) << item2 << right << setw(5) << q2
         << setw(10) << p2 << setw(10) << q2 * p2 << endl;
    cout << left << setw(15) << item3 << right << setw(5) << q3
         << setw(10) << p3 << setw(10) << q3 * p3 << endl;
    cout << "----------------------------------------" << endl;
    cout << left << setw(30) << "Total" << right << setw(10)
         << q1 * p1 + q2 * p2 + q3 * p3 << endl;
    return 0;
}

// operators.cpp - Arithmetic, relational and logical operators
#include <iostream>
using namespace std;

int main() {
    int a = 17, b = 5;

    cout << "a + b  = " << a + b << endl;
    cout << "a - b  = " << a - b << endl;
    cout << "a * b  = " << a * b << endl;
    cout << "a / b  = " << a / b << endl;        // integer division
    cout << "a % b  = " << a % b << endl;        // remainder
    cout << "a / 5.0 = " << a / 5.0 << endl;     // real division

    cout << boolalpha;                           // print true/false
    cout << "a > b  : " << (a > b) << endl;
    cout << "a == b : " << (a == b) << endl;
    cout << "(a > 10 && b > 10) : " << (a > 10 && b > 10) << endl;
    cout << "(a > 10 || b > 10) : " << (a > 10 || b > 10) << endl;
    cout << "!(a > b) : " << !(a > b) << endl;
    return 0;
}

// incdec.cpp - Pre and post increment
#include <iostream>
using namespace std;

int main() {
    int x = 5;
    int y = x++;   // y gets 5, then x becomes 6
    cout << "x = " << x << ", y = " << y << endl;

    x = 5;
    y = ++x;       // x becomes 6, then y gets 6
    cout << "x = " << x << ", y = " << y << endl;

    int z = 10;
    z += 5;  cout << "z += 5  -> " << z << endl;
    z *= 2;  cout << "z *= 2  -> " << z << endl;
    z %= 7;  cout << "z %= 7  -> " << z << endl;
    return 0;
}

// swap.cpp - Swap two numbers (two methods)
#include <iostream>
using namespace std;

int main() {
    int a = 10, b = 20;
    cout << "Before: a = " << a << ", b = " << b << endl;

    // Method 1: using a third variable
    int temp = a;
    a = b;
    b = temp;
    cout << "After method 1: a = " << a << ", b = " << b << endl;

    // Method 2: without a third variable
    a = a + b;   // a = 30 (20 + 10)
    b = a - b;   // b = 20 (30 - 10)
    a = a - b;   // a = 10 (30 - 20)
    cout << "After method 2: a = " << a << ", b = " << b << endl;
    return 0;
}

// casting.cpp - Implicit and explicit type conversion
#include <iostream>
using namespace std;

int main() {
    int total = 427, subjects = 5;

    float avg1 = total / subjects;                 // integer division first
    float avg2 = (float)total / subjects;          // C-style cast
    float avg3 = static_cast<float>(total) / 4;    // C++ style cast

    cout << "avg1 = " << avg1 << endl;
    cout << "avg2 = " << avg2 << endl;
    cout << "avg3 = " << avg3 << endl;

    char grade = 'A';
    int code = grade;              // implicit: char -> int
    cout << "Code of A = " << code << endl;

    double price = 99.75;
    int rupees = (int)price;       // fraction is dropped
    cout << "Rupees = " << rupees << endl;
    return 0;
}

